var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
var objects = scene.GetRootGameObjects().SelectMany(r => r.GetComponentsInChildren<UnityEngine.Transform>(true)).Select(t => t.gameObject).ToArray();
var matches = objects.Where(o => System.Text.RegularExpressions.Regex.IsMatch(o.name, "^SM[_ ]?Rails", System.Text.RegularExpressions.RegexOptions.IgnoreCase)).ToArray();
var roots = matches.Where(o => !matches.Any(p => p != o && o.transform.IsChildOf(p.transform))).ToArray();
var candidates = UnityEditor.AssetDatabase.GetAllAssetPaths().Where(p => p.StartsWith("Assets/") && System.IO.Path.GetFileName(p).IndexOf("rails", System.StringComparison.OrdinalIgnoreCase) >= 0 && !UnityEditor.AssetDatabase.IsValidFolder(p)).ToArray();
return new { scene = scene.path, dirty = scene.isDirty, playing = UnityEditor.EditorApplication.isPlaying, compiling = UnityEditor.EditorApplication.isCompiling, matches = matches.Length, roots = roots.Select(o => new { name = o.name, id = o.GetInstanceID(), path = UnityEditor.AnimationUtility.CalculateTransformPath(o.transform, null), children = o.GetComponentsInChildren<UnityEngine.Transform>(true).Select(t => t.name).ToArray() }).ToArray(), candidates = candidates.Select(p => new { path = p, guid = UnityEditor.AssetDatabase.AssetPathToGUID(p), dependencies = UnityEditor.AssetDatabase.GetDependencies(p, false) }).ToArray() };
